/* @lc app=leetcode id=3372 lang=kotlin */ class Solution { fun cn(e: Array<IntArray>, d: Int): IntArray = (e.size + 1).let { n -> e.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { s -> if (d < 0) 0 else HashSet<Int>().also { it.add(s) }.let { seen -> generateSequence(listOf(s)) { f -> f.flatMap { g[it].orEmpty() }.filter { seen.add(it) }.takeIf { it.isNotEmpty() } }.take(d + 1).sumOf { it.size } } } } } fun maxTargetNodes(edges1: Array<IntArray>, edges2: Array<IntArray>, k: Int): IntArray = cn(edges2, k - 1).max().let { b -> cn(edges1, k).map { it + b }.toIntArray() } }